        'keywords' => ['بررسی امنیت لینوکس', 'امن‌سازی سرور لینوکس', 'اسکریپت امنیتی Bash', 'امنیت اوبونتو', 'امن‌سازی SSH', 'ممیزی فایروال لینوکس', 'کنترل‌های همسو با CIS'],
