$code = function (string $s, string $language = 'bash') use ($escape): string {
    $markup = $escape($s);
    if ($language === 'bash') {
        // Tokenize before HTML escaping; preserve every byte of copyable source.
        $tokens = preg_split("~('[^']*'|--[a-z][a-z-]*|\\b(?:sudo|chmod|bash|shellcheck)\\b|\\./security-audit\\.sh)~", $s, -1, PREG_SPLIT_DELIM_CAPTURE);
        $markup = '';
        foreach ($tokens as $i => $token) {
            if ($i % 2 === 0) { $markup .= $escape($token); continue; }
            $type = str_starts_with($token, "'") ? 'string' : (str_starts_with($token, '--') ? 'option' : 'command');
            $markup .= '<span class="code-token-'.$type.'">'.$escape($token).'</span>';
        }
    }
    return '<div class="article-code"><div class="article-code-header"><span class="article-code-label">'.$escape($language).'</span><button type="button" class="article-copy-button">Copy</button></div><pre dir="ltr"><code class="language-'.$language.'">'.$markup.'</code></pre></div>';
};
